import{_ as n,C as c,o as h,c as i,j as e,a as d,E as o,a5 as r}from"./chunks/framework.CINlqUGR.js";const q=JSON.parse('{"title":"代码块","description":"","frontmatter":{},"headers":[],"relativePath":"components/code-block.md","filePath":"components/code-block.md","lastUpdated":1787174994000}'),s={name:"components/code-block.md"},b={id:"代码块",tabindex:"-1"};function p(u,t,k,g,m,x){const l=c("Badge"),a=c("XhDemo");return h(),i("div",null,[e("h1",b,[t[0]||(t[0]=d("代码块 ",-1)),o(l,{type:"info",text:"code-block"}),t[1]||(t[1]=d()),t[2]||(t[2]=e("a",{class:"header-anchor",href:"#代码块","aria-label":'Permalink to "代码块 <Badge type="info" text="code-block" />"'},"​",-1))]),t[3]||(t[3]=r('<p>一段带语法着色的代码，支持流式追加时的未闭合状态。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>文档、AI 回复、日志详情里展示代码。</li><li>代码是流式生成的，需要边来边着色。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>只是一小段行内标识：用<a href="./typography">排印</a>的 <code>code</code> 形态。</li><li>展示的是运行日志：用<a href="./log">日志</a>。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li><code>complete</code> 标出这段代码是否已经写完；未闭合时着色器不会因为语法不完整而崩掉。</li><li><code>highlighter</code> 是一个着色端口，接哪个着色器由宿主决定。</li><li><code>wrap</code> 决定长行折行还是横滚；行号栏由作者自己加。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="基础用法" tabindex="-1">基础用法 <a class="header-anchor" href="#基础用法" aria-label="Permalink to &quot;基础用法&quot;">​</a></h3><p>代码原文由宿主给，组件负责数行数、预撑高度并铺记号；语言角标带 aria-hidden，是纯装饰</p>',10)),o(a,{src:"code-block/01-basic"}),t[4]||(t[4]=e("h3",{id:"流式未闭合",tabindex:"-1"},[d("流式未闭合 "),e("a",{class:"header-anchor",href:"#流式未闭合","aria-label":'Permalink to "流式未闭合"'},"​")],-1)),t[5]||(t[5]=e("p",null,"complete 为 false 时默认不着色：半截代码的词法本来就不稳，每来一个记号整块变一次色比不着色更难看",-1)),o(a,{src:"code-block/02-streaming"}),t[6]||(t[6]=e("h3",{id:"着色端口",tabindex:"-1"},[d("着色端口 "),e("a",{class:"header-anchor",href:"#着色端口","aria-label":'Permalink to "着色端口"'},"​")],-1)),t[7]||(t[7]=e("p",null,"着色是可换的端口：认不出的语言退回纯文本，接自己的实现组件侧一行不用改，传 null 则整个关掉",-1)),o(a,{src:"code-block/03-highlighter"}),t[8]||(t[8]=e("h3",{id:"行号栏",tabindex:"-1"},[d("行号栏 "),e("a",{class:"header-anchor",href:"#行号栏","aria-label":'Permalink to "行号栏"'},"​")],-1)),t[9]||(t[9]=e("p",null,"行号是作者摆在代码块旁边的一栏，对齐靠行高与内边距这几个公开变量，行数由原文自己数",-1)),o(a,{src:"code-block/04-line-numbers"}),t[10]||(t[10]=r('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-code-block&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhCodeBlock</code></td></tr><tr><td>状态机</td><td>无，<code>connect</code> 直接由 props 算属性</td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/code-block.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;code-block&quot;</code>：<strong><code>root</code></strong> · <code>lang-label</code> · <strong><code>pre</code></strong> · <strong><code>code</code></strong> · <code>token</code></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>code</code></td><td><code>string</code></td><td>是</td><td></td></tr><tr><td><code>complete</code></td><td><code>boolean</code></td><td></td><td>代码块是否已闭合，未闭合时按行数预撑高度。</td></tr><tr><td><code>highlighter</code></td><td><code>HighlighterPort</code></td><td></td><td>着色实现。不给就是纯文本，给了也允许它返回 null（语言不认识之类），同样退回纯文本。 未闭合的块默认不着色，见 {@link highlightWhileStreaming}。</td></tr><tr><td><code>highlightWhileStreaming</code></td><td><code>boolean</code></td><td></td><td>块还没闭合时也着色，默认 false。 默认关是因为半截代码的词法本来就不稳——引号、括号随时会配上， 每来一个 token 整块变一次色，看着比不着色更糟。</td></tr><tr><td><code>lang</code></td><td><code>string</code></td><td></td><td>围栏语言标注，为空时按 plaintext 处理。</td></tr><tr><td><code>wrap</code></td><td><code>boolean</code></td><td></td><td>长行自动换行，默认关（长行横向滚动）。开启后缩进照旧保留，只是行尾会折下来， 窄栏与移动端读长行时不必左右拖。</td></tr></tbody></table><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>connect</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>lang</code></td><td><code>string</code></td><td></td></tr><tr><td><code>lineCount</code></td><td><code>number</code></td><td>行数。行号栏由作者自己渲染——组件不给这个部件是有意的： 行号要与代码并排就得由 root 拿走 flex/grid 排布权，而 root 刻意不设 display， 排布归作者。拿这个数配一列 span 即可，行高与代码块共用同一个令牌。</td></tr><tr><td><code>tokens</code></td><td><code>readonly CodeToken[]</code></td><td>着色结果。空数组表示这一次不着色，作者按 <code>code</code> 原样渲染纯文本即可。 非空时逐个记号渲成元素，<code>getTokenProps</code> 给出该带的属性。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getLangLabelProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getPreProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getCodeProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTokenProps</code></td><td><code>(token: CodeToken) =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/WCAG21/Techniques/general/G202" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Tab</code></td><td>代码块在 Tab 序列中</td><td>&lt;pre&gt; 自身可聚焦，随后方向键的横向滚动交给浏览器，组件不接管</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>lang-label</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr></tbody></table><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/code-block.css</code> 按部件选择：<code>[data-scope=&quot;code-block&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-complete</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-lang</code></td><td>props.lang?.trim() || CODE_BLOCK_FALLBACK_LANG</td></tr><tr><td><code>pre</code></td><td><code>data-complete</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>pre</code></td><td><code>data-wrap</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>code</code></td><td><code>data-lang</code></td><td>props.lang?.trim() || CODE_BLOCK_FALLBACK_LANG</td></tr><tr><td><code>code</code></td><td><code>data-wrap</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>token</code></td><td><code>data-kind</code></td><td>token.kind</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件皮肤读的组件级令牌，写在组件自身或任意祖先上都生效。缺省值来自<a href="./../guide/theme">设计令牌</a>，不设即按缺省走。</p><p><code>--xh-code-block-bg</code> · <code>--xh-code-block-comment-fg</code> · <code>--xh-code-block-font</code> · <code>--xh-code-block-keyword-fg</code> · <code>--xh-code-block-keyword-weight</code> · <code>--xh-code-block-label-fg</code> · <code>--xh-code-block-label-font-size</code> · <code>--xh-code-block-label-px</code> · <code>--xh-code-block-label-py</code> · <code>--xh-code-block-line-height</code> · <code>--xh-code-block-number-fg</code> · <code>--xh-code-block-p</code> · <code>--xh-code-block-punctuation-fg</code> · <code>--xh-code-block-radius</code> · <code>--xh-code-block-string-fg</code></p><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>与<a href="./clipboard">剪贴板</a>配合提供复制；放进 AI 的<a href="./thread">会话线程</a>。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>标出语言：读者与着色器都需要它。</li><li>长代码给固定高度加内部滚动，别让一段代码占满整屏。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>把代码放进普通段落里：空白与换行会被折叠掉。</li><li>复制按钮复制的是带行号的文本。</li></ul>',32))])}const P=n(s,[["render",p]]);export{q as __pageData,P as default};
